    // SHOT BOARD (Kanban)
    // ══════════════════════════════════════════════════════════════
    /**
     * The running total against the bought runtime.
     *
     * A film runs as long as it runs and this stays empty for one. A commercial
     * is bought by the second, and this is the screen where an overlong spot
     * gets fixed — finding out at export is too late to be cheap.
     *
     * Read from the free deliverables check, which measures the cut the same
     * way the conform does: two answers to "how long is this" is how a board
     * and an export come to disagree.
     */
    async function loadShotboardRuntime() {
        const host = document.getElementById('shotboardRuntime');
        if (!host || !state.currentProject) return;
        host.innerHTML = '';
        let v;
        try { v = await api(`/projects/${state.currentProject.id}/deliverables/check`); }
        catch (err) { return; }
        if (!v.target_duration_ms) return;

        const cut = (v.cut_duration_ms / 1000).toFixed(1);
        const target = (v.target_duration_ms / 1000).toFixed(1);
        const delta = (v.cut_duration_ms - v.target_duration_ms) / 1000;
        const colour = v.on_target ? 'var(--gl-success)' : 'var(--gl-warning,#f59e0b)';
        host.innerHTML = `<span style="color:${colour};font-weight:600;">${cut}s / ${target}s</span>`
            + (v.on_target ? '' : `<span class="text-sm text-muted"> &middot; `
                + `${delta > 0 ? 'over' : 'under'} by ${Math.abs(delta).toFixed(1)}s</span>`);
    }

    async function loadShotBoard() {
        if (!state.currentProject) return;
        setStatus('Loading shots...');
        loadShotboardRuntime();
        try {
            const data = await api('/projects/' + state.currentProject.id + '/shotlist');
            state.shots = data.shots || [];
            /*
             * FIVE columns, because film_shots.status allows five. `failed`
             * had none, and the fallback filed such a shot under `pending` —
             * so a generation that went wrong read as "not started", which is
             * the one reading that stops anybody investigating it.
             */
            const columns = { pending: [], generating: [], complete: [], failed: [], approved: [] };
            state.shots.forEach(s => {
                const col = columns[s.status] || columns.pending;
                col.push(s);
            });

            const labels = { pending: 'Pending', generating: 'Generating', complete: 'Complete',
                             failed: 'Failed', approved: 'Approved' };
            document.getElementById('kanbanBoard').innerHTML = Object.entries(columns).map(([status, shots]) => `
                <div class="kanban-column"
                     ondragover="onShotColumnOver(event)"
                     ondragleave="onShotColumnLeave(event)"
                     ondrop="onShotColumnDrop(event,'${status}')">
                    <div class="kanban-column-header">
                        <span>${labels[status] || status}</span>
                        <span class="count">${shots.length}</span>
                    </div>
                    ${shots.length === 0 ? '<p class="text-sm text-muted" style="text-align:center;padding:20px 0;">Empty</p>' :
                    shots.map(s => `
                        <div class="kanban-card" draggable="true"
                             ondragstart="onShotDragStart(event,'${s.id}')"
                             ondragend="onShotDragEnd(event)"
                             ondragover="onShotDragOver(event)"
                             ondrop="onShotDrop(event,'${s.id}')"
                             onclick="openShotDetail('${s.id}')" style="cursor:pointer;">
                            <img src="${API_BASE}/film/storyboards/${state.currentProject.id}/${esc(s.shot_code)}.png?w=480"
                                 style="width:100%;height:60px;object-fit:cover;border-radius:4px;margin-bottom:6px;display:block;" onerror="this.style.display='none'">
                            <div class="shot-code">&#9776; Sc${s.scene_number} / ${esc(s.shot_code)}</div>
                            <div class="shot-meta">${esc(s.location || '')} ${s.duration_ms ? '&middot; ' + (s.duration_ms/1000).toFixed(1) + 's' : ''}${s.transition_in_type && s.transition_in_type !== 'cut' ? ' &middot; ' + esc(s.transition_in_type) : ''}</div>
                        </div>`).join('')}
                </div>`).join('');
            setStatus(state.shots.length + ' shot(s)');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

