    // FILM-147: SHOT DRAG-DROP REORDER
    // ══════════════════════════════════════════════════════════════
    let dragShotId = null;

    function onShotDragStart(e, shotId) {
        dragShotId = shotId;
        e.dataTransfer.effectAllowed = 'move';
        e.target.style.opacity = '0.5';
    }

    function onShotDragEnd(e) {
        e.target.style.opacity = '1';
        dragShotId = null;
        document.querySelectorAll('.shot-drop-zone').forEach(z => z.classList.remove('active'));
    }

    function onShotDragOver(e) {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
    }

    /*
     * MOVING A SHOT THROUGH THE BOARD.
     *
     * The cards were already draggable and `onShotDrop` REORDERS — dropping one
     * card on another changes the running order and nothing else. The column
     * carried no ondrop at all, so a card could never cross columns, and
     * `PUT /shots/:id` did not accept `status`: there was no route by which a
     * person could change a shot's status, by drag or otherwise. Only the
     * pipeline ever wrote it.
     *
     * Dropping on the column the card already sits in is a no-op rather than a
     * write: a fumbled drag should not cost a round trip or a status event.
     */
    function onShotColumnOver(e) { e.preventDefault(); e.currentTarget.classList.add('drop-target'); }
    function onShotColumnLeave(e) { e.currentTarget.classList.remove('drop-target'); }

    async function onShotColumnDrop(e, status) {
        e.preventDefault();
        e.currentTarget.classList.remove('drop-target');
        if (!dragShotId) return;
        const shot = (state.shots || []).find(x => x.id === dragShotId);
        if (!shot || shot.status === status) return;
        try {
            await api('/shots/' + dragShotId, { method: 'PUT', body: JSON.stringify({ status }) });
            setStatus(`${shot.shot_code || 'Shot'} → ${status}`);
            loadShotBoard();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function onShotDrop(e, targetShotId) {
        e.preventDefault();
        // Reordering within a column must not also be read as a status move.
        e.stopPropagation();
        if (!dragShotId || dragShotId === targetShotId || !state.currentProject) return;

        // Build new order: move dragShotId before targetShotId
        const shotIds = state.shots.map(s => s.id);
        const fromIdx = shotIds.indexOf(dragShotId);
        const toIdx = shotIds.indexOf(targetShotId);
        if (fromIdx === -1 || toIdx === -1) return;

        shotIds.splice(fromIdx, 1);
        shotIds.splice(toIdx, 0, dragShotId);

        try {
            await api('/projects/' + state.currentProject.id + '/shots/reorder', {
                method: 'POST',
                body: JSON.stringify({ shot_ids: shotIds })
            });
            setStatus('Shots reordered');
            loadShotBoard();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

