    function closeShotDetail() {
        const existing = document.getElementById('shotDetailPanel');
        if (existing) existing.remove();
        shotDetailPanel = null;
    }

    async function loadShotDetailNotes(shotId) {
        try {
            const data = await api('/shots/' + shotId + '/notes');
            const notes = data.notes || [];
            const el = document.getElementById('shotDetailNotes');
            if (!el) return;
            el.innerHTML = `<h4 class="mb-8">Notes (${notes.length})</h4>` +
                notes.map(n => `<div class="card mb-8" style="padding:8px;">
                    <span class="badge">${esc(n.note_type)}</span>
                    <p class="text-sm">${esc(n.content)}</p>
                    <p class="text-sm text-muted">${new Date(n.created_at).toLocaleDateString()}</p>
                </div>`).join('') +
                `<div style="margin-top:8px;">
                    <textarea id="shotDetailNoteInput" rows="2" placeholder="Add a note..." style="width:100%;font-size:12px;"></textarea>
                    <button class="btn btn-primary btn-sm" style="margin-top:4px;" onclick="addShotDetailNote('${shotId}')">Add Note</button>
                </div>`;
        } catch (err) { /* ignore */ }
    }

    async function addShotDetailNote(shotId) {
        const content = document.getElementById('shotDetailNoteInput')?.value?.trim();
        if (!content) return;
        try {
            await api('/shots/' + shotId + '/notes', { method: 'POST', body: JSON.stringify({ content, note_type: 'direction' }) });
            loadShotDetailNotes(shotId);
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function runShotPipeline(shotId) {
        setStatus('Starting pipeline for shot...');
        try {
            await api('/shots/' + shotId + '/render', { method: 'POST', body: JSON.stringify({ step: 'keyframe' }) });
            setStatus('Pipeline run started');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    // ══════════════════════════════════════════════════════════════
    // FILM-143: TRANSITION PICKER
    // ══════════════════════════════════════════════════════════════
    async function saveShotTransition(shotId) {
        const data = {
            transition_in_type: document.getElementById('shotTransitionIn')?.value || 'cut',
            transition_in_duration_ms: parseInt(document.getElementById('shotTransitionInMs')?.value) || 0,
            transition_out_type: document.getElementById('shotTransitionOut')?.value || 'cut',
            transition_out_duration_ms: parseInt(document.getElementById('shotTransitionOutMs')?.value) || 0,
        };
        try {
            await api('/shots/' + shotId + '/transition', { method: 'PUT', body: JSON.stringify(data) });
            setStatus('Transition saved');
            // Update local state
            const shot = state.shots.find(s => s.id === shotId);
            if (shot) Object.assign(shot, data);
        } catch (err) { setStatus('Error saving transition: ' + err.message); }
    }

