    // FILM-155: A/B VERSION COMPARISON
    // ══════════════════════════════════════════════════════════════
    async function openABCompare(shotId) {
        try {
            const data = await api('/shots/' + shotId + '/versions');
            const versions = data.versions || [];
            if (versions.length < 2) { setStatus('Need at least 2 versions to compare'); return; }
            closeShotDetail();

            const panel = document.createElement('div');
            panel.id = 'abComparePanel';
            panel.className = 'card';
            panel.style.cssText = 'position:fixed;right:0;top:0;bottom:0;width:700px;z-index:200;overflow-y:auto;border-radius:0;border-left:1px solid var(--gl-border-subtle);box-shadow:-4px 0 20px rgba(0,0,0,0.3);';

            const vOpts = versions.map((v, i) => `<option value="${v.version_number}">${v.version_number} (${new Date(v.created_at).toLocaleDateString()})</option>`).join('');

            panel.innerHTML = `
                <div class="flex-between mb-16">
                    <h2>A/B Compare</h2>
                    <button class="btn btn-secondary btn-sm" onclick="closeABCompare()">&times;</button>
                </div>
                <div style="display:flex;gap:12px;margin-bottom:16px;">
                    <div class="form-group" style="flex:1;"><label>Version A</label><select id="abVersionA" onchange="loadABCompare('${shotId}')">${vOpts}</select></div>
                    <div class="form-group" style="flex:1;"><label>Version B</label><select id="abVersionB" onchange="loadABCompare('${shotId}')">${vOpts.replace('selected','')}</select></div>
                </div>
                <div style="position:relative;margin-bottom:16px;">
                    <div style="display:flex;gap:8px;" id="abImages">
                        <div style="flex:1;text-align:center;"><div class="text-sm text-muted mb-8">A</div><div id="abImgA" style="background:var(--gl-bg-header);min-height:150px;border-radius:8px;overflow:hidden;"></div></div>
                        <div style="flex:1;text-align:center;"><div class="text-sm text-muted mb-8">B</div><div id="abImgB" style="background:var(--gl-bg-header);min-height:150px;border-radius:8px;overflow:hidden;"></div></div>
                    </div>
                </div>
                <div class="mb-8"><label class="text-sm text-muted">Crossfade</label><input type="range" id="abSlider" min="0" max="100" value="50" style="width:100%;" oninput="updateABCrossfade(this.value)"></div>
                <div id="abDiffPanel" style="margin-top:16px;"></div>
            `;
            document.body.appendChild(panel);

            // Default: A = first, B = second
            document.getElementById('abVersionB').selectedIndex = 1;
            loadABCompare(shotId);
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function loadABCompare(shotId) {
        const a = document.getElementById('abVersionA')?.value;
        const b = document.getElementById('abVersionB')?.value;
        if (!a || !b) return;
        try {
            const data = await api('/shots/' + shotId + '/versions/compare?a=' + a + '&b=' + b);
            const imgA = document.getElementById('abImgA');
            const imgB = document.getElementById('abImgB');
            if (data.version_a?.thumbnail_path) imgA.innerHTML = `<img src="${API_BASE}/film/${data.version_a.thumbnail_path}" style="width:100%;display:block;" onerror="this.parentElement.innerHTML='<p class=\\'text-sm text-muted\\' style=\\'padding:30px;\\'>No image</p>'">`;
            else imgA.innerHTML = '<p class="text-sm text-muted" style="padding:30px;">No image</p>';
            if (data.version_b?.thumbnail_path) imgB.innerHTML = `<img src="${API_BASE}/film/${data.version_b.thumbnail_path}" style="width:100%;display:block;" onerror="this.parentElement.innerHTML='<p class=\\'text-sm text-muted\\' style=\\'padding:30px;\\'>No image</p>'">`;
            else imgB.innerHTML = '<p class="text-sm text-muted" style="padding:30px;">No image</p>';

            // Show parameter diff
            const diff = data.param_diff || {};
            const keys = Object.keys(diff);
            const diffEl = document.getElementById('abDiffPanel');
            if (keys.length === 0) {
                diffEl.innerHTML = '<p class="text-sm text-muted">No parameter differences.</p>';
            } else {
                diffEl.innerHTML = `<h4 class="mb-8" style="font-size:12px;text-transform:uppercase;letter-spacing:1px;color:var(--gl-text-muted);">Parameter Differences</h4>
                    <table style="width:100%;font-size:12px;">
                    <tr style="color:var(--gl-text-muted);"><th style="text-align:left;">Field</th><th>A</th><th>B</th></tr>
                    ${keys.map(k => `<tr><td style="color:var(--gl-brand-pink);">${esc(k)}</td><td>${esc(String(diff[k].a ?? '-'))}</td><td>${esc(String(diff[k].b ?? '-'))}</td></tr>`).join('')}
                    </table>`;
            }
        } catch (err) { setStatus('Error loading comparison: ' + err.message); }
    }

    function updateABCrossfade(val) {
        const imgA = document.getElementById('abImgA');
        const imgB = document.getElementById('abImgB');
        if (imgA) imgA.style.opacity = 1 - val / 100;
        if (imgB) imgB.style.opacity = val / 100;
    }

    function closeABCompare() {
        const p = document.getElementById('abComparePanel');
        if (p) p.remove();
    }
